use zwen_core::tool_completion::ToolDecoder;
#[test]fn fragmented_tool_arguments_decode_without_parsing_the_report_as_json(){let mut d=ToolDecoder::default();for v in [serde_json::json!({"choices":[{"delta":{"tool_calls":[{"index":0,"id":"call_1","type":"function","function":{"name":"read_paper_page","arguments":"{\"pa"}}]},"finish_reason":null}]}),serde_json::json!({"choices":[{"delta":{"tool_calls":[{"index":0,"function":{"arguments":"ge\":2}"}}]},"finish_reason":"tool_calls"}]})]{assert!(!d.accept(&v.to_string()).unwrap());}assert!(d.accept("[DONE]").unwrap());let t=d.finish().unwrap();assert_eq!(t.calls[0].function.arguments,"{\"page\":2}");}
#[test]fn malformed_or_unfinished_tool_streams_fail_closed(){for data in [r#"{"choices":[{"delta":{"tool_calls":[{"index":4}]},"finish_reason":"tool_calls"}]}"#,r#"{"choices":[{"delta":{},"finish_reason":"tool_calls"}]}"#]{let mut d=ToolDecoder::default();if d.accept(data).is_ok(){let _=d.accept("[DONE]");assert!(d.finish().is_err());}}let mut d=ToolDecoder::default();assert!(d.accept("[DONE]").is_err());}
#[test]fn final_markdown_can_contain_json_fences_and_trailing_braces(){let mut d=ToolDecoder::default();d.accept(&serde_json::json!({"choices":[{"delta":{"content":"# Report\n```json\n{}\n``` }"},"finish_reason":"stop"}]}).to_string()).unwrap();d.accept("[DONE]").unwrap();assert!(d.finish().unwrap().content.ends_with('}'));}
#[test]fn null_placeholder_fields_in_tool_argument_fragments_are_not_new_values(){let mut d=ToolDecoder::default();for part in [serde_json::json!({"index":0,"id":"call_ok","type":"function","function":{"name":"read_paper_page","arguments":"{"}}),serde_json::json!({"index":0,"id":null,"type":null,"function":{"name":null,"arguments":"\"page\":1}"}})]{d.accept(&serde_json::json!({"choices":[{"delta":{"tool_calls":[part]},"finish_reason":null}]}).to_string()).unwrap();}d.accept(r#"{"choices":[{"delta":{},"finish_reason":"tool_calls"}]}"#).unwrap();d.accept("[DONE]").unwrap();assert_eq!(d.finish().unwrap().calls[0].function.arguments,"{\"page\":1}");}
